function solve({config,state,event}) {
  const cap=config.capacity;
  const records=state&&Array.isArray(state.r)?state.r.map(x=>({id:x.id,s:x.s,e:x.e,u:x.u})):[];
  let status;
  if(event.type==='cancel'){
    let i=-1;
    for(let j=0;j<records.length;j++){
      if(records[j].id===event.id){i=j;break;}
    }
    if(i<0) status='missing';
    else { records.splice(i,1); status='cancelled'; }
  } else if(event.type==='reserve'){
    let duplicate=false;
    for(const x of records) if(x.id===event.id){duplicate=true;break;}
    let ok=!duplicate&&Number.isSafeInteger(event.start)&&Number.isSafeInteger(event.end)&&Number.isSafeInteger(event.units)&&event.start>=0&&event.start<event.end&&event.units>=1&&event.units<=cap;
    if(ok){
      for(let t=event.start;t<event.end&&ok;t++){
        let used=event.units;
        for(const x of records) if(t>=x.s&&t<x.e) used+=x.u;
        if(used>cap) ok=false;
      }
    }
    if(ok){
      records.push({id:event.id,s:event.start,e:event.end,u:event.units});
      status='reserved';
    } else status='rejected';
  } else status='rejected';
  const active=records.map(x=>x.id).sort();
  let units=0;
  for(const x of records) units+=x.u;
  return {state:{r:records},output:{status,active,units}};
}
